@Service
public class ExclusiveFileUpdater {
    @Autowired private RedissonClient redisson;
    @Autowired private S3Client s3;

    public void updateFile(String key, byte[] content) {
        RLock lock = redisson.getLock("lock:" + key);
        lock.lock(10, TimeUnit.SECONDS);
        try {
            // BUG: Long GC pause or slow I/O can outlive the 10-second lock TTL
            // No fencing token is sent to S3 to validate ownership
            s3.putObject(PutObjectRequest.builder().bucket("data").key(key).build(), RequestBody.fromBytes(content));
        } finally {
            if (lock.isHeldByCurrentThread()) {
                lock.unlock();
            }
        }
    }
}

